constants:
export AWS_ACCESS_KEY_ID=$(AccessKey)
export AWS_SECRET_ACCESS_KEY=$(SecretKey)
export AWS_DEFAULT_REGION=us-west-2
cd $(System.DefaultWorkingDirectory)/build_scripts/
export MINT_VERSION="Mint-"$(<version.txt)
aws s3 cp $(System.DefaultWorkingDirectory)/build_scripts/final_installer/$MINT_VERSION.dmg s3://download-mintnet-work/install/
aws s3 cp $(System.DefaultWorkingDirectory)/build_scripts/final_installer/$MINT_VERSION.dmg.sha256 s3://download-mintnet-work/install/
aws s3 cp $(System.DefaultWorkingDirectory)/build_scripts/final_installer/$MINT_VERSION.dmg.torrent s3://download-mintnet-work/torrents/

